A = [
dict(n=75, slug="text-to-video", title="How Does an AI Make a Video From a Sentence?", topic="Text-to-video",
buzz='"Text-to-video." Type a sentence, get a realistic video clip. It went from blurry experiments to cinema-like clips in a couple of years.',
hw='A flipbook: draw a slightly different picture on every page, flick through, and it moves.\n\nThat\'s the hello world: **text-to-video** AI generates a sequence of frames that match your sentence and change smoothly from one to the next, so it looks like real motion.',
step='Most video generators extend diffusion (write-up 73): start from noise and clean it step by step, but for many frames at once, so they stay consistent. The hard part is keeping things the same across frames: the same face, the same shirt, objects that don\'t melt or vanish.\n\nThey learn from huge amounts of video, which is why they also inherit questions about consent and copyright.',
met='AI video tools from major tech companies, ads and social media clips made with AI, and short "AI films".',
name='**Text-to-video** generation.',
words=[("Frame","one still image in a video."),("Temporal consistency","keeping things the same from frame to frame."),("Video diffusion","diffusion applied across many frames.")],
notit='It isn\'t filming anything real. Watch for physics slips: hands merging, objects appearing, impossible motion. And it isn\'t automatically free to use commercially; check the tool\'s terms.',
take=["Use it for drafts, storyboards and concepts.","Check every clip for odd details before publishing.","Label AI-made video clearly."],
close="A flipbook, drawn by AI from one sentence.",
q="Can you still tell AI video from real video?",
scene='Draw a slightly different picture on every page.\nFlick through: it moves.',
hook="Text-to-video AI draws that flipbook from a single sentence.",
extra="Impressive, and still watch the hands."),

dict(n=76, slug="deepfake", title="How Can a Video of Someone Be Fake?", topic="Deepfake",
buzz='"Deepfake." Fake videos of politicians, celebrities and CEOs make headlines. Some have been used to steal millions.',
hw='Take a video of an actor speaking. Replace their face, frame by frame, with someone else\'s face, matching every expression. Now it looks like the other person said it.\n\nThat\'s the hello world: a **deepfake** is AI-made video, audio or images that show a real person doing or saying something they never did.',
step='The AI learns what a person\'s face and voice look and sound like from photos and recordings, then generates new footage in their likeness. Tools that once needed experts now run in apps.\n\nThat\'s why scams have shifted: fake video calls from a "CFO" asking for urgent transfers, fake celebrity endorsements, and fake evidence.',
met='News of video-call scams, fake endorsement ads, and election misinformation clips.',
name='A **deepfake**.',
words=[("Deepfake","realistic fake media of a real person."),("Face swap","replacing one face with another in video."),("Synthetic media","AI-generated images, audio or video.")],
notit='Not every edited video is a deepfake, and not every deepfake is harmful (films use the technology with consent). The problem is deception without consent.',
take=["Verify urgent money or access requests through a second channel.","Agree a code word with family for emergency calls.","Be sceptical of shocking clips until a trusted source confirms them."],
close="Real face. Fake moment.",
q="Has your company prepared staff for deepfake calls?",
scene='A video call from your CFO.\n"Transfer the money now. It\'s urgent."',
hook="It might not be your CFO. That's a deepfake.",
extra="Verify urgent requests on a second channel."),

dict(n=77, slug="voice-cloning", title="Can an AI Copy Your Voice From a Few Seconds of Audio?", topic="Voice cloning",
buzz='"Voice cloning." Audiobooks, dubbing and assistants use it. So do scammers.',
hw='A good mimic listens to someone for a while, then speaks in their voice: the tone, the accent, the little pauses.\n\nThat\'s the hello world: **voice cloning** is AI learning a person\'s voice from recordings, then saying anything in that voice.',
step='The AI captures what makes a voice distinctive and applies it to new text. Some tools need minutes of clean audio; others claim usable results from seconds.\n\nUses include dubbing films into other languages in the actor\'s own voice, and giving a voice back to people who lose theirs to illness. Misuses include fake calls asking family for money.',
met='AI dubbing of videos, audiobook narration, and news of "family emergency" scam calls.',
name='**Voice cloning**, a form of **speech synthesis**.',
words=[("Voice clone","a synthetic copy of a real voice."),("Text-to-speech","turning text into spoken audio."),("Consent","permission from the person whose voice it is.")],
notit='A familiar voice on a call is no longer proof of identity. Don\'t use voice alone to approve payments or access.',
take=["Stop using voice alone as a security check.","Agree a family code word for emergencies.","Get written consent before cloning anyone's voice."],
close="A familiar voice isn't proof any more.",
q="Would you recognise a cloned voice on a call?",
scene='Your mother calls. Her voice, her tone.\n"I need money now."',
hook="Voice cloning can copy a voice from a few seconds of audio.",
extra="A familiar voice isn't proof any more."),

dict(n=78, slug="ai-avatar", title="Who Is That Presenter, If Nobody Filmed Them?", topic="AI avatar",
buzz='"AI avatars." Training videos, ads and news clips now feature presenters who were never filmed for them.',
hw='Record yourself once, speaking for a few minutes. Then type any script, and a video of "you" presents it, lips matching every word, in any language.\n\nThat\'s the hello world: an **AI avatar** is a digital presenter, based on a real person or invented, that speaks whatever text you give it.',
step='The AI combines a generated or recorded face, lip movement matched to the words, and a voice (often cloned, write-up 77). Companies use it to make training videos, product explainers and multilingual versions quickly.\n\nUsed openly and with consent, it saves time. Used to impersonate someone, it becomes a deepfake (write-up 76).',
met='Corporate training videos, multilingual marketing clips, and AI news presenters.',
name='An **AI avatar**, also called a **digital human**.',
words=[("Avatar","a digital character representing a person."),("Lip sync","matching mouth movements to speech."),("Disclosure","telling viewers it's AI-made.")],
notit='An AI avatar isn\'t the person and doesn\'t think. It reads the script it\'s given, mistakes included.',
take=["Get consent and contracts before making anyone's avatar.","Tell viewers when a presenter is AI.","Review scripts as carefully as with a real presenter."],
close="Filmed once, presenting forever.",
q="Would you watch a training video presented by an AI avatar?",
scene='Record yourself once.\nThen "you" present any script, in any language.',
hook="That's an AI avatar: a presenter who was never filmed for this video.",
extra="Fine with consent and disclosure. A deepfake without."),

dict(n=79, slug="digital-twin", title="What's a Digital Twin, and Why Do Factories Want One?", topic="Digital twin",
buzz='"Digital twin." Factories, cities and hospitals talk about them. Now the term is used for AI copies of people too.',
hw='A model railway that copies a real railway exactly, and updates live: every real train\'s position shows on the model instantly. Now you can test "what if we add a train?" on the model first.\n\nThat\'s the hello world: a **digital twin** is a live virtual copy of something real, used to monitor it and test changes safely.',
step='Sensors feed real data into the twin: a factory machine\'s temperature, a building\'s energy use, a city\'s traffic. Engineers simulate changes on the twin before trying them in reality. AI helps predict failures and suggest fixes.\n\nThe term is now also used for AI copies of people that answer like them, such as AI "twins" for hiring. Same idea: a stand-in you can ask questions.',
met='Manufacturing and city-planning dashboards, and the AI twins that recruiters can question (my Today in AI No. 012 covers one).',
name='A **digital twin**.',
words=[("Digital twin","a live virtual copy of a real thing."),("Sensor","a device feeding real-world data in."),("Simulation","testing changes on the copy first.")],
notit='A twin is only as good as its data. An outdated or simplified twin can give confident wrong answers about the real thing.',
take=["Ask how often the twin's data updates.","Test predictions against reality regularly.","For person-twins, check consent and accuracy."],
close="A live copy to test on before touching the real thing.",
q="What would you build a digital twin of?",
scene='A model railway that mirrors the real one, live.\nTest the new train on the model first.',
hook="A digital twin is a live copy you can safely experiment on.",
extra="Factories, cities, and now people."),

dict(n=82, slug="embodied-ai", title="When Does AI Get a Body?", topic="Embodied AI",
buzz='"Embodied AI." "Physical AI." Humanoid robots are back in the headlines, now with AI brains.',
hw='Knowing how to describe making tea is one thing. Picking up a mug without crushing it, filling it without spilling, and carrying it across a cluttered kitchen is another.\n\nThat\'s the hello world: **embodied AI** is AI that sees, moves and acts in the physical world through a body, like a robot.',
step='Language models learned from text. Embodied AI also needs to learn from sight, touch and movement: how objects feel, fall and break. Training happens partly in simulations and world models (write-up 81), then on real robots.\n\nNewer robots use large AI models to understand instructions like "tidy the table", then turn them into precise movements. The physical world is far less forgiving than a chat: a wrong step can break things or hurt people.',
met='Warehouse robots, robot vacuums, self-driving cars, and demos of humanoid robots folding laundry.',
name='**Embodied AI**, also called **physical AI**.',
words=[("Robotics","building machines that move and act."),("Humanoid","a robot shaped like a person."),("Sim-to-real","training in simulation, then on real machines.")],
notit='Impressive demo videos aren\'t the same as reliable products. Many are carefully set up or remote-controlled. Ask what works unscripted.',
take=["Separate demos from deployed products.","Ask about safety testing for any robot near people.","Expect narrow, repetitive tasks first, not general helpers."],
close="Describing tea is easy. Making it is hard.",
q="Would you let a humanoid robot into your home?",
scene='Describing how to make tea: easy.\nCarrying a full mug across a cluttered kitchen: hard.',
hook="Embodied AI is AI with a body, learning the hard part.",
extra="Robots, self-driving cars, and the next wave of demos."),
]
